package in.aicon.pocket;
import android.content.*;import android.app.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35)
public class DuePlansTest {
 Context c;@Before public void setup(){c=RuntimeEnvironment.getApplication();DuePlans.prefs(c).edit().clear().commit();Shadows.shadowOf((Application)c).grantPermissions(android.Manifest.permission.POST_NOTIFICATIONS);}
 @Test public void dateTriggersOnlyAfterPromisedDayAndNoRepeat()throws Exception{String key=DuePlans.key("scope","loan");DuePlans.put(c,key,"scope","2026-11-15",true);long when=DuePlans.when("2026-11-15");assertEquals(java.time.LocalDate.of(2026,11,16),java.time.Instant.ofEpochMilli(when).atZone(java.time.ZoneId.systemDefault()).toLocalDate());assertFalse(DuePlans.consumeDue(c,when-1));assertTrue(DuePlans.consumeDue(c,when));assertFalse(DuePlans.consumeDue(c,when+86400000));assertFalse(DuePlans.get(c,key).optBoolean("autoSms"));}
 @Test public void legacyAutomaticSmsGrantIsScrubbedWithoutSending()throws Exception{String key=DuePlans.key("scope","loan");DuePlans.put(c,key,"scope","2026-11-15",true);JSONObject j=DuePlans.get(c,key).put("autoSms",true).put("phone","+919000000001").put("sim",1).put("attempt","old").put("smsStatus","old");DuePlans.prefs(c).edit().putString(key,j.toString()).commit();assertTrue(DuePlans.consumeDue(c,DuePlans.when("2026-11-15")));JSONObject after=DuePlans.get(c,key);assertFalse(after.has("autoSms"));assertFalse(after.has("phone"));assertFalse(after.has("attempt"));assertFalse(after.has("sim"));assertFalse(after.has("smsStatus"));assertEquals("2026-11-15",after.getString("date"));assertTrue(after.getBoolean("reminder"));assertTrue(after.getBoolean("notified"));assertFalse(DuePlans.consumeDue(c,Long.MAX_VALUE));}
 @Test public void changedDateClearsAutomaticGrant()throws Exception{String key=DuePlans.key("scope","loan");DuePlans.put(c,key,"scope","2026-11-15",true);JSONObject j=DuePlans.get(c,key).put("autoSms",true);DuePlans.prefs(c).edit().putString(key,j.toString()).commit();DuePlans.put(c,key,"scope","2026-11-16",true);assertFalse(DuePlans.get(c,key).optBoolean("autoSms"));}
}
